const app=document.getElementById('app');
let progress={},storageAvailable=true,session=null;
const maxStars=lessons.reduce((n,l)=>n+l.missions.reduce((s,m)=>s+m.questions.length,0),0);
function islandScore(l){return l.missions.reduce((n,m,i)=>n+(progress[l.id+'-'+i]||0),0)}
function islandMax(l){return l.missions.reduce((n,m)=>n+m.questions.length,0)}
function played(l){return l.missions.some((m,i)=>progress[l.id+'-'+i]!==undefined)}
try{
 const current=localStorage.getItem('palavras-v2');
 const saved=JSON.parse(current||'{}');
 for(const l of lessons)for(const [i,m] of l.missions.entries()){
  const key=l.id+'-'+i,n=saved?.[key];
  if(Number.isInteger(n)&&n>=0&&n<=m.questions.length)progress[key]=n;
 }
 if(!current){
  const previous=JSON.parse(localStorage.getItem('palavras-v1')||'{}');
  for(const l of lessons){const n=previous?.[l.id];if(Number.isInteger(n)&&n>=0&&n<=5)progress[l.id+'-0']=n}
  localStorage.setItem('palavras-v2',JSON.stringify(progress));
 }
}catch{storageAvailable=false}
function save(){try{localStorage.setItem('palavras-v2',JSON.stringify(progress))}catch{storageAvailable=false}}
function total(){return Object.values(progress).reduce((a,b)=>a+b,0)}
const owl=`<svg viewBox="0 0 400 300" role="img" aria-label="Uma corujinha exploradora lendo um livro em uma ilha verde"><ellipse cx="206" cy="262" rx="154" ry="22" fill="#cfdbc1"/><path d="M60 248q135-55 289 0" fill="#acbf94"/><path d="M96 224q-42-48-18-68 34 10 18 68M306 232q-16-55 15-68 23 28-15 68" fill="#72926a"/><path d="M111 245q-7-63-38-83M302 244l20-67" stroke="#557547" fill="none" stroke-width="4"/><path d="M139 208q-25-59-8-114l32 18q37-18 78 0l33-18q19 55-8 114z" fill="#ac724c"/><ellipse cx="201" cy="184" rx="65" ry="69" fill="#ba8356"/><path d="M145 150q20-42 56-8 40-34 62 8l-12 45H154z" fill="#f7e6bc"/><circle cx="173" cy="159" r="23" fill="#fffaf0"/><circle cx="230" cy="159" r="23" fill="#fffaf0"/><circle cx="177" cy="162" r="8" fill="#304b38"/><circle cx="225" cy="162" r="8" fill="#304b38"/><circle cx="179" cy="159" r="2.5" fill="white"/><circle cx="227" cy="159" r="2.5" fill="white"/><path d="m194 179 8 12 8-12" fill="#e0ac4b"/><path d="M126 123q76-35 152 0l-10-20q-7-45-66-42-53 3-63 39z" fill="#688563"/><path d="M145 101q58-17 123 2" fill="none" stroke="#476a4c" stroke-width="9"/><path d="M122 205q46-11 80 9 38-22 82-9l-6 50q-40-7-76 8-39-15-75-8z" fill="#fff8df" stroke="#4d7251" stroke-width="5"/><path d="M202 215v47M137 220l48 8m-47 7 44 7m35-14 48-8m-47 21 44-7" stroke="#d2c7a8" stroke-width="3"/><path d="M135 182q-26 11-12 41 18 7 21-17M268 183q26 9 16 39-18 9-23-16" fill="#ac724c"/><path d="m312 64 4 12 12 4-12 4-4 12-4-12-12-4 12-4zM96 80l3 8 9 3-9 3-3 9-3-9-9-3 9-3z" fill="#d7ac4b"/><path d="M279 46q8-13 16-4t-8 20" stroke="#8ca47b" stroke-width="4" fill="none"/></svg>`;
function notice(){return storageAvailable?'':'<p class="save-notice">O navegador não permitiu salvar. Você pode jogar, mas o progresso poderá se perder ao fechar.</p>'}
function home(){session=null;app.innerHTML=`<section class="hero"><div><span class="pill">🌿 Aprender pode ser uma aventura</span><h1>Um mundo de palavras<br>para <em>descobrir.</em></h1><p>Explore, brinque e aprenda português. Cada descoberta é um novo passo na sua aventura!</p><button class="primary" id="start">Vamos explorar <span>→</span></button></div><div class="scene"><span class="floating one">á ê ó ✦</span>${owl}<span class="floating two">Era uma vez…</span></div></section><section id="ilhas"><div class="path-label"><div><span class="eyebrow">Sua trilha de descobertas</span><h2 style="margin-top:8px">Qual será a aventura de hoje?</h2><p>Escolha uma ilha. Você pode começar por qualquer uma!</p></div><span class="small-tag">✦ ${total()} de ${maxStars} estrelas</span></div><div class="cards">${lessons.map((l,i)=>`<article class="card" style="--wash:${l.color}"><span class="number">ILHA 0${i+1}</span><div class="icon">${l.icon}</div><h3>${l.title}</h3><p>${l.desc}</p>${played(l)?`<span class="done">★ ${islandScore(l)} de ${islandMax(l)} estrelas conquistadas</span>`:''}<button data-lesson="${l.id}">${played(l)?'Explorar de novo':'Começar aventura'} <span>→</span></button></article>`).join('')}</div></section><aside class="tip"><span>💡</span><p><strong>Aqui, cada tentativa ensina!</strong><br>Leia as dicas, experimente e tente de novo. Aprender leva prática, e você está no caminho.</p></aside>${notice()}`;document.getElementById('start').onclick=()=>document.getElementById('ilhas').scrollIntoView({behavior:'smooth'});app.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>location.hash='aprender/'+b.dataset.lesson)}
function intro(l){
 session=null;
 app.innerHTML=`<div class="lesson" style="--wash:${l.color}"><a class="back" href="#inicio">← Voltar às ilhas</a><div class="lesson-title"><span class="pill">${l.icon} ILHA ${lessons.indexOf(l)+1} • APRENDER</span><h1>${l.title}</h1><p>${l.subtitle}</p></div><section class="lesson-box"><h2>Uma dica antes de começar</h2><p>${l.intro}</p><div class="example">${l.example}</div><p>${l.detail}</p><p class="note">💡 ${l.note}</p></section><div class="path-label"><div><h2>Escolha sua missão</h2><p>Cinco desafios por vez. Você escolhe por onde começar!</p></div></div><div class="missions">${l.missions.map((m,i)=>`<article class="card" style="--wash:${l.color}"><span class="eyebrow">MISSÃO 0${i+1}</span><h3>${m.title}</h3><p>5 desafios • sem pressa</p>${progress[l.id+'-'+i]!==undefined?`<span class="done">★ ${progress[l.id+'-'+i]} de 5 estrelas</span>`:''}<button data-mission="${i}">${progress[l.id+'-'+i]!==undefined?'Praticar de novo':'Começar missão'} <span>→</span></button></article>`).join('')}</div></div>`;
 app.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>startMission(l,Number(b.dataset.mission)));
}
function startMission(island,i){
 const mission=island.missions[i];
 const l={...island,...mission,id:island.id+'-'+i,islandId:island.id};
 session={l,index:0,score:0,missed:[],answered:false};
 question();window.scrollTo(0,0);
}
function question(){const s=session,l=s.l,q=l.questions[s.index];s.answered=false;app.innerHTML=`<div class="lesson" style="--wash:${l.color}"><button class="back" id="leave">← Sair da atividade</button><div class="progress-row"><span>${l.icon} ${l.title}</span><span>Desafio ${s.index+1} de ${l.questions.length}</span></div><div class="track" role="progressbar" aria-label="Desafios concluídos" aria-valuemin="0" aria-valuemax="${l.questions.length}" aria-valuenow="${s.index}"><span style="width:${s.index/l.questions.length*100}%"></span></div>${l.passage?`<article class="passage"><h3>📖 ${l.passage.title}</h3><p>${l.passage.text}</p></article>`:''}<section class="lesson-box"><span class="eyebrow">Sua vez de descobrir</span><h2 class="question">${q.q}</h2><div class="answers">${q.options.map((v,i)=>`<button class="answer" data-answer="${i}"><span aria-hidden="true">${String.fromCharCode(65+i)}. </span>${v}</button>`).join('')}</div><div id="feedback" aria-live="polite" aria-atomic="true"></div><div class="lesson-actions"><button class="secondary" id="hint">💡 Ver uma dica</button><span class="note">Cada tentativa vale uma descoberta.</span></div><div id="hint-text"></div></section></div>`;document.getElementById('leave').onclick=()=>{location.hash='inicio'};document.getElementById('hint').onclick=()=>{document.getElementById('hint-text').innerHTML=`<p class="note">${l.passage?'Releia a história e procure as pistas ligadas à pergunta.':l.intro}</p>`};app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)))}
function answer(choice){const s=session;if(s.answered)return;s.answered=true;const q=s.l.questions[s.index],ok=choice===q.a;if(ok)s.score++;else s.missed.push(s.index);app.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;const n=Number(b.dataset.answer);if(n===q.a)b.classList.add('correct');else if(n===choice)b.classList.add('wrong')});document.getElementById('feedback').innerHTML=`<div class="feedback ${ok?'success':''}"><strong>${ok?'✦ Muito bem! Você descobriu!':'🌱 Vamos aprender com esta tentativa!'}</strong><p>${ok?'':`A resposta é: <strong>${q.options[q.a]}</strong><br>`}${q.why}</p></div><div class="lesson-actions"><button class="primary" id="next">${s.index===s.l.questions.length-1?'Ver minha conquista':'Próximo desafio'} <span>→</span></button></div>`;document.getElementById('next').onclick=()=>{s.index++;if(s.index===s.l.questions.length)finish();else{question();window.scrollTo({top:0,behavior:'smooth'})}}}
function finish(){const s=session,l=s.l;progress[l.id]=Math.max(progress[l.id]||0,s.score);save();app.innerHTML=`<div class="lesson"><section class="lesson-box result celebrate"><span class="result-icon">${s.score===5?'🏆':'🌟'}</span><h1>Aventura concluída!</h1><p>Você praticou ${l.title.toLowerCase()} e fez novas descobertas.</p><div class="stars" aria-label="${s.score} de 5 estrelas">${'★'.repeat(s.score)}${'☆'.repeat(5-s.score)}</div><p>${s.score} de 5 respostas certas nesta rodada.<br>${s.score===5?'Você encontrou todas as pistas. Que tal explorar outra ilha?':'Continue praticando! Leia as explicações e experimente outra vez.'}</p>${s.missed.length?`<div class="passage" style="text-align:left"><h3>Para reforçar</h3>${s.missed.map(i=>`<p><strong>${l.questions[i].q}</strong><br>${l.questions[i].why}</p>`).join('')}</div>`:''}<div class="lesson-actions"><button class="secondary" id="again">↻ Praticar de novo</button><button class="primary" id="choose-mission">Escolher outra missão →</button></div>${notice()}</section></div>`;document.getElementById('choose-mission').onclick=()=>{intro(lessons.find(island=>island.id===l.islandId));window.scrollTo(0,0)};document.getElementById('again').onclick=()=>{session={l,index:0,score:0,missed:[],answered:false};question();window.scrollTo(0,0)};window.scrollTo({top:0,behavior:'smooth'})}
function achievements(){session=null;app.innerHTML=`<a class="back" href="#inicio">← Voltar às ilhas</a><div class="lesson-title"><span class="eyebrow">Pequenas descobertas, grandes passos</span><h1>Minhas conquistas</h1><p>Seu melhor resultado em cada missão fica guardado aqui.</p><span class="pill">⭐ ${total()} de ${maxStars} estrelas</span></div><div class="summary">${lessons.map(l=>`<article class="badge"><span>${!played(l)?'🌱':l.icon}</span><h3>${l.title}</h3><p>${!played(l)?'Uma aventura espera por você!':`${islandScore(l)} de ${islandMax(l)} estrelas`}</p><a href="#aprender/${l.id}">${!played(l)?'Começar':'Praticar mais'} →</a></article>`).join('')}</div><div class="tip"><span>⭐</span><p><strong>A prática faz você avançar.</strong><br>Repita uma ilha para conquistar mais estrelas. Guardamos sempre o seu melhor resultado em cada missão.</p></div><p class="note">O progresso é salvo neste navegador e neste dispositivo.</p>${notice()}`}
function route(){const hash=location.hash.slice(1);document.getElementById('nav-home').classList.toggle('active',hash!=='conquistas');document.getElementById('nav-stars').classList.toggle('active',hash==='conquistas');if(hash==='conquistas')achievements();else if(hash.startsWith('aprender/')){const l=lessons.find(l=>l.id===hash.split('/')[1]);if(l)intro(l);else home()}else home();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);route();
